original_answer:
The midpoint of $(-1,7)$ and $(5,-5)$ is
\[\left( \frac{-1 + 5}{2}, \frac{7 - 2}{2} \right) = (2,1).\]This tells us that the vector being reflected over is a scalar multiple of $\begin{pmatrix} 2 \\ 1 \end{pmatrix}.$  We can then assume that the vector being reflected over is $\begin{pmatrix} 2 \\ 1 \end{pmatrix}.$

[asy]
usepackage("amsmath");

unitsize(0.5 cm);

pair A, B, M, O, R, S;

O = (0,0);
A = (-1,7);
R = (5,-5);
B = (-4,3);
S = (0,-5);
M = (A + R)/2;

draw((-4,-2)--(4,2),red + dashed);
draw(O--M,red,Arrow(6));
draw((-5,0)--(5,0));
draw((0,-6)--(0,8));
draw(O--A,Arrow(6));
draw(O--R,Arrow(6));
draw(A--R,dashed,Arrow(6));
draw(O--B,Arrow(6));
draw(O--S,Arrow(6));
draw(B--S,dashed,Arrow(6));
label("$\begin{pmatrix} -1 \\ 7 \end{pmatrix}$", A, NW);
label("$\begin{pmatrix} 5 \\ -5 \end{pmatrix}$", R, SE);
label("$\begin{pmatrix} -4 \\ 3 \end{pmatrix}$", B, NW);
label("$\begin{pmatrix} 2 \\ 1 \end{pmatrix}$", M, N);
[/asy]

The projection of $\begin{pmatrix} -4 \\ 3 \end{pmatrix}$ onto $\begin{pmatrix} 2 \\ 1 \end{pmatrix}$ is
\[\operatorname{proj}_{\begin{pmatrix} 2 \\ 1 \end{pmatrix}} \begin{pmatrix} -4 \\ 3 \end{pmatrix} = \frac{\begin{pmatrix} -4 \\ 3 \end{pmatrix} \cdot \begin{pmatrix} 2 \\ 1 \end{pmatrix}}{\begin{pmatrix} 2 \\ 1 \end{pmatrix} \cdot \begin{pmatrix} 2 \\ 1 \end{pmatrix}} \begin{pmatrix} 2 \\ 1 \end{pmatrix} = \frac{-5}{5} \begin{pmatrix} 2 \\ 1 \end{pmatrix} = \begin{pmatrix} -2 \\ -1 \end{pmatrix}.\]Hence, the reflection of $\begin{pmatrix} -4 \\ 3 \end{pmatrix}$ is $2 \begin{pmatrix} -2 \\ -1 \end{pmatrix} - \begin{pmatrix} -4 \\ 3 \end{pmatrix} = \boxed{\begin{pmatrix} 0 \\ -5 \end{pmatrix}}.$

question:
A frustum of a right circular cone is formed by cutting a small cone off of the top of a larger cone. If a particular frustum has a lower base radius of 6 inches, an upper base radius of 3 inches, and a height of 4 inches, what is its lateral surface area?  (The lateral surface area of a cone or frustum is the curved surface excluding the base(s).)

[asy]size(200);
import three; defaultpen(linewidth(.8)); currentprojection = orthographic(0,-3,0.5); pen dots = linetype("0 3") + linewidth(1);
real h = 2.3, ratio = (91-24)/(171-24);
picture p1, p2; /* p1 is left-hand picture */
triple A = (0,0,0), B = (0,0,h); draw(p1,(-1,0,0)..(0,-1,0)..(1,0,0)); draw(p1,(-1,0,0)..(0,1,0)..(1,0,0),dots); draw(p1,(-1,0,0)--B--(1,0,0));
add(p1);

triple vlift = (0,0,0.5);

path3 toparc1 = shift((0,0,h*(1-ratio)))*scale3(ratio)*((-1,0,0)..(0,1,0)..(1,0,0)), toparc2 = shift((0,0,h*(1-ratio)))*scale3(ratio)*((1,0,0)..(0,-1,0)..(-1,0,0));
draw(p2,(-1,0,0)..(0,-1,0)..(1,0,0)); draw(p2,(-1,0,0)..(0,1,0)..(1,0,0),dots);

draw(p2,(-1,0,0)--ratio*(-1,0,0)+(1-ratio)*B^^ratio*(1,0,0)+(1-ratio)*B--(1,0,0));

draw(p2,shift(vlift)*(ratio*(-1,0,0)+(1-ratio)*B--B--ratio*(1,0,0)+(1-ratio)*B));

draw(p2,toparc1--toparc2); draw(p2,shift(vlift)*toparc1,dots); draw(p2,shift(vlift)*toparc2);

draw(p2,shift(vlift)*((1-ratio)*B--B),linewidth(0.7)); dot(p2,shift(vlift)*((1-ratio)*B),linewidth(1.5));
label(p2,"frustum",(0,0,h/4));

add(shift((3.4,0,0))*p2);

[/asy]

